        case PLANS.PASS_PRO:
            return ADDON_NAMES.MEMBER_SCRIBE_PASS_PRO;
        case PLANS.VPN_BUSINESS:
            return ADDON_NAMES.MEMBER_SCRIBE_VPN_BIZ;
        case PLANS.PASS_BUSINESS:
            return ADDON_NAMES.MEMBER_SCRIBE_PASS_BIZ;
        case PLANS.VPN_PRO:
            return ADDON_NAMES.MEMBER_SCRIBE_VPN_PRO;
        case PLANS.FAMILY:
            return ADDON_NAMES.MEMBER_SCRIBE_FAMILY;
        default:
            return ADDON_NAMES.MEMBER_SCRIBE_MAILPLUS;
    }
};

export const getAssistantUpsellConfig = (
    upsellRef: string,
    user: UserModel,
    isOrgAdmin: boolean,
    selectedPlan: SelectedPlan
): OpenCallbackProps | undefined => {
    if (user.isSubUser) {
        return undefined;
    }

    if (isOrgAdmin) {
        const addonName = paidUserAssistantAddonName(selectedPlan.name);
        return paidMultipleUserUpsellConfig(upsellRef, addonName, selectedPlan);
    }

    if (user.isPaid) {
        const addonName = paidUserAssistantAddonName(selectedPlan.name);
        return paidSingleUserUpsellConfig(upsellRef, selectedPlan.name, addonName, selectedPlan.cycle);
    }

    // Return the free user config if the user is not paid and don't have member in its organization
    return freeUserUpsellConfig(upsellRef);
};

export const getAssistantDowngradeConfig = (
    upsellRef: string,
    selectedPlan: SelectedPlan
): OpenCallbackProps | undefined => {
    return {
        mode: 'upsell-modal',
        /**
         * Removes only Scribe addons and keep all others
         */
        planIDs: removeAddon(selectedPlan.planIDs, isScribeAddon),
        step: SUBSCRIPTION_STEPS.CHECKOUT,
        disablePlanSelection: true,
        cycle: selectedPlan.cycle,
        maximumCycle: selectedPlan.cycle,
        minimumCycle: selectedPlan.cycle,
        upsellRef,
        metrics: {
            source: 'upsells',
        },
    };
};

